(()=>{const key="portfolio-route-transition";const labels={"index.html":"Work","about.html":"About","playground.html":"Playground","contact.html":"Contact","fromanother.html":"FROMANOTHER"};const routeFor=url=>{const path=url.pathname.replace(/\/+$/,"");const file=path.split("/").pop()||"index.html";return file==="about"?"about.html":file};const titleFor=url=>labels[routeFor(url)]||"Work";const makeOverlay=(title)=>{const overlay=document.createElement("div");overlay.className="page-transition";overlay.setAttribute("role","status");overlay.setAttribute("aria-live","polite");const label=document.createElement("span");label.className="page-transition__title";label.textContent=title;overlay.append(label);document.body.append(overlay);return overlay};let entering=null;try{entering=sessionStorage.getItem(key);sessionStorage.removeItem(key)}catch{}if(entering){document.documentElement.classList.add("has-route-transition");const overlay=makeOverlay(entering);requestAnimationFrame(()=>setTimeout(()=>overlay.classList.add("is-leaving"),520));setTimeout(()=>overlay.remove(),1450)}document.addEventListener("click",event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest("a[href]");if(!link||link.target==="_blank"||link.hasAttribute("download"))return;const dest=new URL(link.href,location.href);const route=routeFor(dest);if(dest.origin!==location.origin||!labels[route])return;if(dest.pathname===location.pathname)return;event.preventDefault();let title=labels[route];try{sessionStorage.setItem(key,title)}catch{}makeOverlay(title);setTimeout(()=>location.assign(dest.href),600)})})();